class Solution:
    def findNumber(self) -> int:
        self.ans = 0
        def go(lo, hi, cnt):
            if cnt == 0:
                return
            if hi - lo == 1:
                self.ans |= 1 << lo
                return
            mid = (lo + hi) // 2
            mask = ((1 << mid) - 1) ^ ((1 << lo) - 1)
            c = commonSetBits(mask)
            go(lo, mid, c)
            go(mid, hi, cnt - c)
        go(0, 30, commonSetBits((1 << 30) - 1))
        return self.ans

